// Adopt page: renders the launch recipe from adopt-data.js (generated by tools/gen-guide-adopt.mjs).
// Every string reaches the page through textContent; there are no HTML strings here.
(function () {
  'use strict';

  var A = window.ADOPT;
  var HOSTS = window.GUIDE_HOSTS || { default: 'claude', order: ['claude'], hosts: { claude: { label: 'Claude Code', prefix: '/' } } };
  var THEME_KEY = 'sdd-guide-theme';
  var HOST_KEY = 'sdd-guide-host';
  var TASKS_KEY = 'sdd-adopt-tasks';
  var NEXT = { system: 'light', light: 'dark', dark: 'system' };
  var root = document.documentElement;
  var osQuery = window.matchMedia('(prefers-color-scheme: dark)');
  var $ = function (id) { return document.getElementById(id); };

  /* ---------- Theme (same cycle and storage key as the guide) ---------- */
  var themeButton = $('theme-toggle');
  var choice = 'system';
  try {
    var storedTheme = localStorage.getItem(THEME_KEY);
    if (storedTheme === 'light' || storedTheme === 'dark') choice = storedTheme;
  } catch (e) { /* storage unavailable: follow the OS */ }
  function applyTheme() {
    var theme = choice === 'system' ? (osQuery.matches ? 'dark' : 'light') : choice;
    root.dataset.theme = theme;
    root.style.colorScheme = theme;
    themeButton.querySelector('.btn-label').textContent = 'Theme: ' + choice;
    themeButton.setAttribute('aria-label', 'Theme: ' + choice + '. Switch to ' + NEXT[choice] + '.');
  }
  themeButton.addEventListener('click', function () {
    choice = NEXT[choice];
    try { if (choice === 'system') localStorage.removeItem(THEME_KEY); else localStorage.setItem(THEME_KEY, choice); } catch (e) { /* page view only */ }
    applyTheme();
  });
  if (osQuery.addEventListener) osQuery.addEventListener('change', function () { if (choice === 'system') applyTheme(); });
  else if (osQuery.addListener) osQuery.addListener(function () { if (choice === 'system') applyTheme(); });
  applyTheme();

  /* ---------- DOM helpers ---------- */
  /** Builds an element from a tag, an optional props object (class, text, on* handlers, attributes) and children. */
  function h(tag, props) {
    var el = document.createElement(tag);
    var kids = Array.prototype.slice.call(arguments, 1);
    if (props && typeof props === 'object' && !props.nodeType && !Array.isArray(props)) {
      kids.shift();
      Object.keys(props).forEach(function (k) {
        var v = props[k];
        if (v === null || v === undefined || v === false) return;
        if (k === 'class') el.className = v;
        else if (k === 'text') el.textContent = v;
        else if (k.slice(0, 2) === 'on') el.addEventListener(k.slice(2), v);
        else el.setAttribute(k, v === true ? '' : String(v));
      });
    }
    append(el, kids);
    return el;
  }
  function append(el, kids) {
    (Array.isArray(kids) ? kids : [kids]).forEach(function (k) {
      if (k === null || k === undefined || k === false) return;
      if (Array.isArray(k)) append(el, k);
      else if (typeof k === 'string' || typeof k === 'number') el.appendChild(document.createTextNode(String(k)));
      else el.appendChild(k);
    });
  }

  if (!A || !A.levels) {
    var main = $('content');
    main.insertBefore(h('p', { class: 'note data-missing', role: 'alert' },
      'The Adopt page data did not load. Keep adopt.html next to adopt-data.js, adopt.js and guide.css in docs/guide/ and reopen it.'), main.firstChild);
    return;
  }

  function toast(msg) {
    var t = $('toast');
    t.textContent = msg;
    t.classList.add('show');
    clearTimeout(toast.timer);
    toast.timer = setTimeout(function () { t.classList.remove('show'); }, 1600);
  }
  function copyText(text) {
    function fallback() {
      var ta = h('textarea', { readonly: true, class: 'copy-buffer' });
      ta.value = text;
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand('copy'); toast('Copied'); } catch (e) { toast('Select the text and copy it manually'); }
      document.body.removeChild(ta);
    }
    if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(text).then(function () { toast('Copied'); }, fallback);
    else fallback();
  }

  /* ---------- Inline nodes and blocks from the generator ---------- */
  /** Renders inline nodes: strings, {c} code, {b} bold, {i} italic and {a, href} links. */
  function inline(nodes) {
    return (nodes || []).map(function (n) {
      if (typeof n === 'string') return n;
      if (n.c !== undefined) return h('code', n.c);
      if (n.b) return h('strong', inline(n.b));
      if (n.i) return h('em', inline(n.i));
      if (n.a) return h('a', { href: n.href }, inline(n.a));
      return null;
    });
  }
  function textOf(nodes) {
    return (nodes || []).map(function (n) {
      if (typeof n === 'string') return n;
      if (n.c !== undefined) return n.c;
      return textOf(n.b || n.i || n.a);
    }).join('');
  }

  var stored = {};
  try { stored = JSON.parse(localStorage.getItem(TASKS_KEY) || '{}') || {}; } catch (e) { stored = {}; }
  var taskListeners = [];
  function saveTasks() {
    try { localStorage.setItem(TASKS_KEY, JSON.stringify(stored)); } catch (e) { /* page view only */ }
    taskListeners.forEach(function (fn) { fn(); });
  }
  function taskItem(id, content) {
    var box = h('input', {
      type: 'checkbox', id: id,
      onchange: function () { if (box.checked) stored[id] = true; else delete stored[id]; saveTasks(); }
    });
    box.checked = !!stored[id];
    return h('li', { class: 'adopt-task' }, box, h('label', { for: id }, content));
  }

  function codeBlock(code, lang) {
    var label = lang ? lang + ' snippet' : 'snippet';
    return h('div', { class: 'code adopt-code' },
      h('code', code),
      h('button', { type: 'button', class: 'copy', 'aria-label': 'Copy ' + label, onclick: function () { copyText(code); } }, 'Copy'));
  }
  function table(t, caption) {
    return h('div', { class: 'table-wrap', role: 'region', tabindex: '0', 'aria-label': caption },
      h('table',
        h('thead', h('tr', t.head.map(function (c) { return h('th', { scope: 'col' }, inline(c)); }))),
        h('tbody', t.rows.map(function (r) { return h('tr', r.map(function (c) { return h('td', inline(c)); })); }))));
  }
  /** Renders generator blocks. `scope` makes task checkbox ids unique per place on the page. */
  function blocks(list, scope) {
    var tasks = 0;
    return (list || []).map(function (b, bi) {
      if (b.p) return h('p', inline(b.p));
      if (b.code !== undefined) return codeBlock(b.code, b.lang);
      if (b.table) return table(b.table, textOf(b.table.head[0]) + ' table');
      if (b.tasks) {
        return h('ul', { class: 'adopt-tasks' }, b.tasks.map(function (t) { return taskItem(scope + '-' + bi + '-' + (tasks++), inline(t)); }));
      }
      var items = b.ol || b.ul;
      if (items) {
        return h(b.ol ? 'ol' : 'ul', items.map(function (it, ii) {
          // A single-paragraph item renders inline, so list items keep the list's spacing.
          if (it.length === 1 && it[0].p) return h('li', inline(it[0].p));
          return h('li', blocks(it, scope + '-' + bi + '-' + ii));
        }));
      }
      return null;
    });
  }

  /* ---------- Host selector ---------- */
  function knownHost(id) { return typeof id === 'string' && Object.prototype.hasOwnProperty.call(HOSTS.hosts, id); }
  var host = (function () {
    var m = /[?&]host=([^&#]*)/.exec(location.search || '');
    if (m && knownHost(m[1])) return m[1];
    try { var v = localStorage.getItem(HOST_KEY); if (knownHost(v)) return v; } catch (e) { /* storage unavailable */ }
    return HOSTS.default;
  })();
  var hostBox = $('adopt-host');
  /** The recipe pilots on Claude Code; another host gets its own install steps from host-data.js. */
  function renderHost() {
    hostBox.textContent = '';
    hostBox.hidden = host === HOSTS.default;
    if (hostBox.hidden) return;
    var info = HOSTS.hosts[host];
    var modes = info.install || {};
    var mode = modes.fileCopy || modes[Object.keys(modes)[0]];
    append(hostBox, [
      h('p', h('strong', info.label + ' is an unverified preview.'),
        ' This plan pilots on Claude Code (level 0), and its commands are Claude Code commands. On ' + info.label +
        ', invoke skills with ' + info.prefix + ' (for example ' + info.prefix + 'sdd), and install the kit as below, adding the same --stack and --with flags as in level 1.'),
      mode ? h('ol', mode.steps.map(function (s) { return h('li', s.text, codeBlock(s.code, info.label)); })) : null,
      h('p', h('a', { href: 'index.html?host=' + encodeURIComponent(host) + '#install' }, 'Every ' + info.label + ' install option in the guide'))
    ]);
  }
  var hostSelect = $('host-select');
  HOSTS.order.forEach(function (id) { hostSelect.appendChild(h('option', { value: id }, HOSTS.hosts[id].label)); });
  hostSelect.value = host;
  hostSelect.addEventListener('change', function () {
    host = knownHost(hostSelect.value) ? hostSelect.value : HOSTS.default;
    try { localStorage.setItem(HOST_KEY, host); } catch (e) { /* page view only */ }
    renderHost();
  });

  /* ---------- Page ---------- */
  if (A.version) $('version').textContent = 'v' + A.version;
  else $('version').hidden = true;
  var titleParts = /^([^:]+): (.+)$/.exec(A.title || '');
  if (titleParts) {
    document.querySelector('.adopt-main .kicker').textContent = titleParts[1];
    $('adopt-h').textContent = titleParts[2].charAt(0).toUpperCase() + titleParts[2].slice(1);
  }
  renderHost();
  append($('adopt-intro'), blocks(A.intro, 'intro'));

  var PART_CLASS = { goal: 'callout goal', done: 'callout done', failure: 'callout failure' };
  var EXAMPLE = { laravel: true, drupal: true };
  function levelBody(level) {
    var out = [];
    var examples = null;
    level.parts.forEach(function (p, pi) {
      var content = [h('h3', p.label), blocks(p.blocks, 'l' + level.n + '-' + pi)];
      if (EXAMPLE[p.kind]) {
        if (!examples) {
          examples = h('div', { class: 'adopt-examples' });
          out.push(examples);
        }
        examples.appendChild(h('section', { class: 'adopt-example', 'aria-label': p.label + ' example, level ' + level.n }, content));
        return;
      }
      examples = null;
      out.push(PART_CLASS[p.kind] ? h('div', { class: PART_CLASS[p.kind] }, content) : content);
    });
    return out;
  }
  var levelEls = A.levels.map(function (level) {
    return h('details', { class: 'level', id: level.id },
      h('summary',
        h('h2', { class: 'level-h' },
          h('span', { class: 'level-n' }, 'Level ' + level.n),
          h('span', { class: 'level-title' }, level.title)),
        level.who.length ? h('span', { class: 'level-who' }, inline(level.who)) : null),
      h('div', { class: 'level-body' },
        level.connects.length ? h('p', { class: 'level-connects' }, h('span', { class: 'lbl' }, 'Connects'), ' ', inline(level.connects)) : null,
        levelBody(level)));
  });
  append($('adopt-levels'), levelEls);

  function section(id, title, kids) {
    return h('section', { id: id, 'aria-labelledby': id + '-h', class: 'adopt-section' }, h('h2', { id: id + '-h' }, title), kids);
  }
  append($('adopt-limits'), section(A.limits.id, A.limits.title, blocks(A.limits.blocks, 'limits')));

  var progress = h('p', { class: 'hint', 'aria-live': 'polite' });
  function updateProgress() {
    var n = A.checklist.items.filter(function (it, i) { return stored['check-' + i]; }).length;
    progress.textContent = n + ' of ' + A.checklist.items.length + ' levels ticked on this browser.';
  }
  taskListeners.push(updateProgress);
  var levelById = {};
  A.levels.forEach(function (l) { levelById[l.n] = l; });
  append($('adopt-checklist'), section(A.checklist.id, A.checklist.title, [
    progress,
    h('ul', { class: 'adopt-tasks checklist' }, A.checklist.items.map(function (it, i) {
      var level = levelById[it.level];
      return taskItem('check-' + i, [level ? h('a', { href: '#' + level.id, class: 'level-link' }, 'Level ' + it.level) : null, ' ', inline(it.text)]);
    }))
  ]));
  updateProgress();

  append($('adopt-stuck'), section(A.stuck.id, A.stuck.title,
    table({ head: [['Symptom'], ['Fix']], rows: A.stuck.rows.map(function (r) { return [r.symptom, r.fix]; }) }, 'Symptoms and fixes')));

  /* ---------- Expand, collapse and deep links ---------- */
  function setAll(open) { levelEls.forEach(function (d) { d.open = open; }); }
  $('expand-all').addEventListener('click', function () { setAll(true); });
  $('collapse-all').addEventListener('click', function () { setAll(false); });

  /** Opens the level a hash names: its full id, or the short form #level-<n>. */
  function openFromHash() {
    var id = decodeURIComponent((location.hash || '').slice(1));
    if (!id) return;
    var short = /^level-(\d+)$/.exec(id);
    if (short && levelById[short[1]]) id = levelById[short[1]].id;
    var el = $(id);
    if (!el) return;
    if (el.tagName === 'DETAILS') el.open = true;
    el.scrollIntoView({ block: 'start' });
  }
  window.addEventListener('hashchange', openFromHash);
  openFromHash();
})();
